), mapped_photo_assets as (
  select npa.*, coalesce((select array_agg(mp.member_id order by mp.display_name) from public.member_profiles mp where mp.member_id is not null and mp.notion_source_id = any(npa.notion_member_page_ids)), '{}'::text[]) as mapped_member_ids
  from notion_photo_assets npa
)
insert into public.media_assets (
  title, asset_kind, storage_bucket, storage_path, thumbnail_path, captured_at, photographer, location_label, project_ids, member_ids, event_id, tags, visibility, status, source_confidence, usage_permission, consent_status, source_kind, source_ref, notion_source_id, notion_last_synced_at, reviewed_by, reviewed_at, updated_by
)
select
  title, case when block_type = 'video' then 'video' else 'photo' end, null, null, null, captured_at, null, location_label, '{}'::text[], mapped_member_ids, null,
  array_remove(array['notion_photo_db', 'notion_photo_block', 'verified_2026_06_05', 'needs_storage_import', 'notion_block_type:' || block_type, 'notion_photo_page:' || page_id, 'photo_index:' || block_index::text, case when coalesce(array_length(notion_member_page_ids, 1), 0) > 0 then 'notion_member_relation_present' end, case when coalesce(array_length(notion_project_page_ids, 1), 0) > 0 then 'notion_project_relation_present' end], null),
  'admin_only', 'needs_review', 0.90, 'unknown', 'unknown', 'notion', 'notion:team-armada-photo-db', notion_source_id, timestamptz '2026-06-05 19:55:00+09', null, null, 'codex_notion_company_localdb_history_photo_complete'
from mapped_photo_assets
on conflict (notion_source_id) do update set
  title = excluded.title, asset_kind = excluded.asset_kind, storage_bucket = excluded.storage_bucket, storage_path = excluded.storage_path, thumbnail_path = excluded.thumbnail_path, captured_at = excluded.captured_at, photographer = excluded.photographer, location_label = excluded.location_label, project_ids = excluded.project_ids, member_ids = excluded.member_ids, event_id = excluded.event_id, tags = excluded.tags, visibility = excluded.visibility, status = excluded.status, source_confidence = excluded.source_confidence, usage_permission = excluded.usage_permission, consent_status = excluded.consent_status, source_kind = excluded.source_kind, source_ref = excluded.source_ref, notion_last_synced_at = excluded.notion_last_synced_at, reviewed_by = excluded.reviewed_by, reviewed_at = excluded.reviewed_at, updated_by = excluded.updated_by, updated_at = now();
